return ['domain'=>'zinn-connector','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-connector','pot-creation-date'=>'2026-09-11T18:44:12+00:00','po-revision-date'=>'2026-09-11T18:44:12+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Connector'=>'Zinn® Connector','https://zinndigital.com/wordpress-plugins/zinn-connector'=>'https://zinndigital.com/wordpress-plugins/zinn-connector','Connects this WordPress site to Zinn Digital® so scheduled articles can be published to it. Paste a pairing code from your Zinn® dashboard and the plugin sets up its own credential — nothing is copied by hand.'=>'Připojí tento web WordPress k platformě Zinn Digital® tak, aby na něj bylo možné publikovat naplánované články. Vložte párovací kód ze svého panelu Zinn® a plugin si sám nastaví přihlašovací údaje – nic se nemusí kopírovat ručně.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Uloženo. Zadejte novou hodnotu pro přepsání.','Filter this list…'=>'Filtrovat tento seznam…','Filter this list'=>'Filtrovat tento seznam','Nothing matches that filter.'=>'T tomuto filtru nic neodpovídá.','Add a row'=>'Přidat řádek','Remove this row'=>'Odstranit tento řádek','Remove'=>'Odstranit','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® – přehled','Overview'=>'Přehled','Every Zinn® plugin on this site, and whether it is working.'=>'Každý plugin Zinn® na tomto webu a zda funguje.','No connection is needed for this plugin.'=>'Pro tento plugin není potřeba žádné připojení.','Open settings'=>'Otevřít nastavení','You do not have permission to change these settings.'=>'Nemáte oprávnění ke změně těchto nastavení.','Settings sections'=>'Sekce nastavení','Support'=>'Podpora','Save changes'=>'Uložit změny','Tools'=>'Nástroje','Export settings'=>'Export nastavení','Reset to defaults'=>'Obnovit výchozí nastavení','This puts every setting on this plugin back to its default. Continue?'=>'Tímto se všechna nastavení tohoto pluginu vrátí na výchozí hodnoty. Pokračovat?','Diagnostics for support'=>'Diagnostika pro podporu','Import a settings file'=>'Importovat soubor nastavení','Import'=>'Importovat','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Exportované soubory nikdy neobsahují hesla, tokeny ani klíče API – na novém webu je budete muset zadat znovu.','Settings saved.'=>'Nastavení byla uložena.','Every setting on this plugin is back to its default.'=>'Všechna nastavení tohoto pluginu byla obnovena na výchozí hodnoty.','Done.'=>'Hotovo.','That action is not available.'=>'Tato akce není k dispozici.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tento soubor se nepodařilo přečíst. Vyberte soubor nastavení exportovaný z pluginu Zinn®.','That file is too large to be a settings export.'=>'Tento soubor je příliš velký na to, aby byl exportem nastavení.','That file is not a Zinn® settings export.'=>'Tento soubor není exportem nastavení Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Tento soubor byl exportován z jiného modulu (%s), takže jeho import sem by uložil nastavení, kterým tento modul nerozumí.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Byla importována %d položka nastavení. Hesla a klíče API se do exportu nezahrnují, proto je zadejte znovu.' . "\0" . '%d nastavení importováno. Hesla a klíče API se neexportují, takže je zadejte znovu.' . "\0" . '%d nastavení importováno. Hesla a klíče API se neexportují, takže je zadejte znovu.' . "\0" . '%d nastavení importováno. Hesla a klíče API se neexportují, takže je zadejte znovu.','The archive would be %1$d MB, over the %2$d MB limit set on this site. Raise the limit, or exclude some folders, on the Zinn Digital® → Connector → Backups screen.'=>'Archiv by měl velikost %1$d MB, což překračuje limit %2$d MB nastavený pro tento web. Zvětšete limit nebo vylučte některé složky na obrazovce Zinn Digital® → Connector → Backups.','This site\'s PHP cannot create archives, so a backup could not be made.'=>'PHP tohoto webu nemůže vytvářet archivy, takže nebylo možné vytvořit zálohu.','Could not create a temporary file.'=>'Nepodařilo se vytvořit dočasný soubor.','This site\'s files could not be archived.'=>'Soubory tohoto webu se nepodařilo archivovat.','This site\'s PHP cannot compress archives, so a backup could not be made.'=>'PHP tohoto webu neumí komprimovat archivy, proto se nepodařilo vytvořit zálohu.','A backup of this site needs about %1$s of temporary space and only %2$s is free, so it was not attempted.'=>'Záloha tohoto webu vyžaduje přibližně %1$s dočasného místa a k dispozici je pouze %2$s, takže nebyla spuštěna.','This WordPress user cannot publish posts, so a connection made now could not publish either. Sign in as a user who can, and try again.'=>'Tento uživatel WordPressu nemůže publikovat příspěvky, takže připojení vytvořené nyní by také nemohlo nic publikovat. Přihlaste se jako uživatel, který to dokáže, a zkuste to znovu.','Application passwords are turned off on this site, so we cannot create a credential. Ask your host to enable them, or connect the site with a password you create yourself in your Zinn Digital® dashboard.'=>'Na tomto webu jsou aplikační hesla vypnutá, takže nemůžeme vytvořit přihlašovací údaje. Požádejte svého hostitele o jejich povolení nebo připojte web pomocí hesla, které si sami vytvoříte ve svém panelu Zinn Digital®.','WordPress would not create a credential for this site. Nothing has been sent anywhere.'=>'WordPress se nepodařilo vytvořit přihlašovací údaje pro tento web. Nikam nebylo nic odesláno.','We could not reach Zinn Digital® from this site. Nothing was connected, and the credential we made has been removed. Check the site can make outgoing requests, and try again.'=>'Nepodařilo se nám z tohoto webu kontaktovat Zinn Digital®. Nic nebylo připojeno a pověření, které jsme vytvořili, bylo odstraněno. Zkontrolujte, zda web může odesílat odchozí požadavky, a zkuste to znovu.','Zinn Digital® could not finish connecting this site. The problem is on our side, not with your pairing code — nothing was connected, and the credential we made has been removed. The same pairing code still works: try again in a few minutes.'=>'Zinn Digital® se nepodařilo dokončit připojení tohoto webu. Problém je na naší straně, nikoli s vaším párovacím kódem – nic nebylo připojeno a pověření, které jsme vytvořili, bylo odstraněno. Stejný párovací kód stále funguje: zkuste to za několik minut znovu.','Zinn Digital® did not accept that pairing code. Nothing was connected. Generate a fresh code in your dashboard and try again.'=>'Zinn Digital® nepřijal tento párovací kód. Nic nebylo připojeno. Vygenerujte si ve svém ovládacím panelu nový kód a zkuste to znovu.','Connected. Zinn Digital® can now publish to this site.'=>'Připojeno. Zinn Digital® teď může na tento web publikovat.','Connected'=>'Připojeno','Connecting…'=>'Připojování…','Connected, but something needs attention'=>'Připojeno, ale některé položky vyžadují pozornost','Not connected'=>'Nepřipojeno','Running on your own account'=>'Běží na vašem vlastním účtu','We could not check this'=>'Tohle se nám nepodařilo zkontrolovat','This plugin did not say why. Send a diagnostics report and we will look.'=>'Tento plugin neuvedl důvod. Odešlete diagnostickou zprávu a my se na to podíváme.','Connection status'=>'Stav připojení','Last checked %s ago.'=>'Naposledy zkontrolováno před %s.','(opens in a new tab)'=>'(otevře se na nové kartě)','Send this to Zinn® support'=>'Odeslat na podporu Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Přesně toto bude odesláno – nic jiného a nic skrytého. Vaše hesla, tokeny a klíče API v tom nejsou obsaženy.','The diagnostics report that will be sent'=>'Diagnostická zpráva, která bude odeslána','Copy to clipboard'=>'Kopírovat do schránky','Send this report to Zinn® support'=>'Odešlete tuto zprávu na podporu Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Vytvoříme pro vás tiket podpory a odpovíme vám e-mailem. Pokud jej raději nechcete odesílat, zkopírujte jej výše a vložte jej do tiketu sami.','Copied'=>'Zkopírováno','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Zinn Digital® se nepodařilo z tohoto serveru (%s) kontaktovat. Zkopírujte výše uvedenou zprávu a místo toho otevřete ticket – s vaším nastavením není nic v nepořádku.','Sent. Zinn® support has your report and will reply by email.'=>'Podpora Zinn® obdržela vaše hlášení a odpoví vám e-mailem.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podpora Zinn® obdržela vaše hlášení – reference %s – a odpoví vám e-mailem.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Odeslali jste několik hlášení v krátké době. Počkejte několik minut a zkuste to znovu – ta předchozí dorazila.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® nyní nemohl přijmout hlášení – chyba je na naší straně, nikoli vaší. Zkuste to brzy znovu nebo zkopírujte výše uvedené hlášení do tiketu.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Zpráva byla odmítnuta (HTTP %d). Zkopírujte ji výše a otevřete tiket s uvedením tohoto čísla.','This site’s owner has turned off image uploads for Zinn Digital® in the Zinn® Connector settings.'=>'Vlastník tohoto webu vypnul nahrávání obrázků pro službu Zinn Digital® v nastavení doplňku Zinn® Connector.','This site’s owner has turned off edits to existing articles for Zinn Digital® in the Zinn® Connector settings.'=>'Vlastník tohoto webu zakázal úpravy existujících článků pro Zinn Digital® v nastavení Zinn® Connector.','New article on your site: %s'=>'Nový článek na vašem webu: %s','Zinn Digital® has added an article to your site.

Title: %1$s
Edit it: %2$s
Status: %3$s

Turn these emails off on the Zinn Digital® → Connector → Publishing screen.'=>'Společnost Zinn Digital® přidala na váš web nový článek.

Název: %1$s
Upravit: %2$s
Stav: %3$s

Tyto e-maily můžete vypnout na obrazovce Zinn Digital® → Connector → Publishing.','%s — guides and services'=>'%s – návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Zinn® hosting pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zaběhnuté weby, domény a umístění odkazů. Peníze budou bezpečně uloženy, dokud nebudou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tím živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Náš globální trh pro na volné noze: procházejte více než 10 000 hotových služeb od spisovatelů, designérů, vývojářů a SEO specialistů, nebo zadejte projekt a nechte je přihazovat.','Connector'=>'Konektor','Connection'=>'Připojení','Publishing'=>'Zveřejňování','Backups'=>'Zálohy','Advanced'=>'Pokročilé','Check the connection now'=>'Zkontrolovat připojení nyní','Disconnect this site'=>'Odpojit tento web','This revokes the credential Zinn Digital® uses, so we can no longer publish to this site. Anything already published stays. Continue?'=>'Tímto odvoláte pověření, které Zinn Digital® používá, takže už na tento web nebudeme moci publikovat. Vše, co již bylo publikováno, zůstane zachováno. Chcete pokračovat?','What we may do on this site'=>'Co na tomto webu můžeme dělat','The credential we hold is an ordinary WordPress application password, so WordPress itself decides what is possible. These narrow it further, on your side.'=>'Přihlašovací údaje, které máme, jsou obyčejné aplikační heslo WordPress, takže o tom, co je možné, rozhoduje samotný WordPress. Tyto položky to na vaší straně ještě více zužují.','Publish articles as'=>'Publikovat články jako','Choose “a draft” if you would rather read everything before it goes live.'=>'Zvolte „koncept“, pokud si chcete raději vše přečíst, než to bude zveřejněno.','Published straight away'=>'Publikováno okamžitě','A draft, for me to review'=>'Koncept ke kontrole','Pending review'=>'Čeká na schválení','Scheduled, using the date we send'=>'Naplánováno, pomocí data, které odešleme','Show the author as'=>'Zobrazit autora jako','Which of your users appears as the author. This does not change who we sign in as.'=>'Který z vašich uživatelů se zobrazuje jako autor. To nemění to, kým se přihlašujeme.','Put articles in'=>'Umístit články do','Allow images'=>'Povolit obrázky','Let Zinn Digital® upload images into this site’s media library'=>'Dovolit službě Zinn Digital® nahrávat obrázky do knihovny médií tohoto webu','Turn this off and articles arrive without their images. Nothing already uploaded is removed.'=>'Vypněte tuto možnost a články budou přicházet bez obrázků. Nic z toho, co už je nahráno, nebude odstraněno.','Allow edits'=>'Povolit úpravy','Let Zinn Digital® update an article it published before'=>'Nechte Zinn Digital® aktualizovat článek, který dříve publikoval','Used for corrections and re-optimisation. It never touches anything you wrote yourself.'=>'Používá se pro opravy a reoptimalizaci. Nikdy se nedotkne ničeho, co jste sami napsali.','Tell me when something is published'=>'Upozorněte mě, když bude něco publikováno','Leave blank for no email. One message per article, from your own site.'=>'Pro žádný e-mail ponechte prázdné. Jedna zpráva na článek z vašeho vlastního webu.','Off-site backups'=>'Externí zálohy','This site sends its own backup straight to Zinn® storage. Nothing passes through our servers on the way.'=>'Tento web odesílá vlastní zálohu přímo do úložiště Zinn®. Nic při tom neprochází přes naše servery.','Back this site up to Zinn Digital®'=>'Zálohujte tento web na Zinn Digital®','Backup token'=>'Zálohovací token','Set for you when the site was connected. You will only need to touch this if support asks.'=>'Nastaveno pro vás při připojení webu. Na toto musíte sáhnout pouze v případě, že o to požádá podpora.','Leave these out'=>'Vynechat tyto položky','One path per line, relative to wp-content — for example <code>cache</code> or <code>uploads/backups</code>. Caches and other backup plugins’ folders are the usual candidates.'=>'Jedna cesta na řádek, relativně k wp-content – například <code>cache</code> nebo <code>uploads/backups</code>. Obvyklými kandidáty jsou vyrovnávací paměti (cache) a složky jiných doplňků pro zálohování.','Stop if the archive would exceed'=>'Zastavit, pokud archiv přesáhne','Megabytes. A shared host will usually kill a very large archive part-way; a bound turns that into a message instead of a silent failure.'=>'Megabajty. Sdílený hosting obvykle velmi velký archiv v polovině ukončí; omezení z toho udělá zprávu namísto tichého selhání.','Detailed logging'=>'Podrobné protokolování','Record what this plugin does, for support'=>'Zaznamenejte, co tento plugin dělá, pro účely podpory','Kept on this site, capped at the last 50 entries, and included in a diagnostics report. Turn it on before reproducing a problem.'=>'Uchováváno na tomto webu, omezeno na posledních 50 záznamů a zahrnuto ve zprávě o diagnostice. Zapněte to před reprodukcí problému.','On uninstall'=>'Při odinstalaci','Delete this plugin’s settings when it is uninstalled'=>'Při odinstalování odstranit nastavení tohoto pluginu','Uninstalling never revokes the application password — that is deliberate, so uninstalling to try something else does not break your publishing. Use Disconnect above if you want the credential gone.'=>'Odinstalování nikdy nezruší heslo aplikace – to je záměrné, takže odinstalace kvůli vyzkoušení něčeho jiného nepřeruší vaše publikování. Pokud chcete přihlašovací údaje odstranit, použijte možnost Odpojit výše.','The user we sign in as'=>'Uživatel, pod kterým se přihlašujeme','The site’s default category'=>'Výchozí kategorie webu','Connect this site again'=>'Znovu připojit tento web','Connect this site'=>'Připojit tento web','Open your Zinn Digital® dashboard, go to Content → Other sites, and press “Get a pairing code”. Paste it below.'=>'Otevřete svůj řídicí panel Zinn Digital®, přejděte na Obsah → Další weby a stiskněte „Získat párovací kód“. Vložte jej níže.','Connecting again creates a fresh credential and leaves the old one in place — use Disconnect first if you want the old one gone.'=>'Opětovné připojení vytvoří nové pověření a to staré ponechá na místě – pokud chcete to staré odstranit, použijte nejprve Odpojit.','Pairing code'=>'Párovací kód','It expires thirty minutes after you generate it, and can only be used once.'=>'Platnost vyprší třicet minut po jeho vytvoření a lze jej použít pouze jednou.','You are not allowed to connect this site.'=>'Nemáte oprávnění připojit tento web.','This site is not connected to Zinn Digital®.'=>'Tento web není propojen se společností Zinn Digital®.','Nothing is wrong — it has simply not been paired yet. Get a pairing code from your Zinn® dashboard and paste it into this plugin’s settings.'=>'Nic není v nepořádku – dosud pouze neproběhlo spárování. Získejte párovací kód ze svého ovládacího panelu Zinn® a vložte jej do nastavení tohoto pluginu.','Open my Zinn® dashboard'=>'Otevřít můj panel Zinn®','The connection is broken.'=>'Připojení je přerušeno.','The WordPress user the credential belonged to (%s) no longer exists on this site, so nothing we send can be published. Connect again as a user who can publish.'=>'Uživatel WordPress, kterému přihlašovací údaje patřily (%s), na tomto webu již neexistuje, takže nic, co odešleme, nelze publikovat. Připojte se znovu jako uživatel, který může publikovat.','The “Zinn Digital® (publishing)” application password has been deleted from this site, so we can no longer sign in. Connect again to create a new one — nothing else was lost.'=>'Heslo aplikace „Zinn Digital® (publishing)“ bylo z tohoto webu odstraněno, takže se již nemůžeme přihlásit. Připojte se znovu a vytvořte nové – nic jiného se neztratilo.','See this site’s application passwords'=>'Zobrazit aplikační hesla tohoto webu','Connected, but publishing would fail.'=>'Připojeno, ale publikování by selhalo.','The credential belongs to %s, and that user can no longer publish posts. Sign-in still works, so nothing looks wrong until an article is due. Give that user the ability to publish, or connect again as somebody who can.'=>'Přihlašovací údaje patří uživateli %s, který již nemůže publikovat příspěvky. Přihlášení stále funguje, takže vše vypadá v pořádku, dokud není nutné vydat článek. Umožněte tomuto uživateli publikovat nebo se znovu připojte jako někdo, kdo tuto oprávnění má.','Edit that user'=>'Upravit tohoto uživatele','Connected here — we could not reach Zinn Digital® to confirm.'=>'Připojeno zde — nepodařilo se nám kontaktovat službu Zinn Digital® pro potvrzení.','Connected, but your Zinn® account needs attention.'=>'Připojeno, ale váš účet u Zinn® vyžaduje pozornost.','Connected to Zinn Digital®.'=>'Připojeno k Zinn Digital®.','Connected to Zinn Digital® as %s.'=>'Připojeno k Zinn Digital® jako %s.','Publishing as'=>'Publikovat jako','Zinn® site ID'=>'ID webu Zinn®','This server could not reach api.zinndigital.com (%s). That is usually a firewall or an outbound-connection rule on your host, not a problem with your Zinn® account — publishing may still be working.'=>'Tento server se nemohl připojit k adrese api.zinndigital.com (%s). Obvykle se jedná o problém brány firewall nebo pravidla odchozího připojení na vašem hostiteli, nikoli o problém s vaším účtem u Zinn® – publikování může stále fungovat.','Zinn Digital® answered with an error of its own — that is our end, not yours. Publishing is unaffected while this clears.'=>'Zinn Digital® odpověděl vlastní chybou – to je na naší straně, ne na vaší. Publikování není touto chybou ovlivněno.','Your Zinn® account is not currently able to publish to this site. Your dashboard says why.'=>'Váš účet Zinn® momentálně nemůže na tento web publikovat. Důvody najdete na svém panelu.','Zinn Digital® answered HTTP %d, which we do not recognise. Send a diagnostics report from the Support tab and we will look — do not change anything here first.'=>'Zinn Digital® vrátil kód HTTP %d, který nerozpoznáme. Odešlete diagnostickou zprávu z karty Podpora a my se na to podíváme – nic zde předtím neměňte.','Check again now'=>'Zkontrolovat znovu nyní','Checked. The connection is live.'=>'Zkontrolováno. Připojení je aktivní.','We could not remove the application password, so this site is still connected. Delete “Zinn Digital® (publishing)” on your profile screen and try again — we have changed nothing.'=>'Nepodařilo se nám odstranit aplikační heslo, takže tento web je stále připojen. Smažte položku „Zinn Digital® (publishing)“ na obrazovce svého profilu a zkuste to znovu – nic jsme nezměnili.','Disconnected. The application password has been revoked, so Zinn Digital® can no longer publish to this site. Nothing already published was touched.'=>'Odpojeno. Heslo aplikace bylo zrušeno, takže Zinn Digital® již nemůže na tento web publikovat. Nic, co již bylo publikováno, nebylo změněno.','That file could not be read from this server, so nothing was uploaded.'=>'Tento soubor nebylo možné z tohoto serveru přečíst, takže se nic nenahrálo.','This site could not stream the upload, so nothing was sent.'=>'Tento web nemohl streamovat nahrávaný soubor, takže nic nebylo odesláno.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Tento soubor má velikost %1$s a PHP tohoto webu nemá cURL, takže maximální velikost pro nahrání je %2$s.','The upload could not be completed.'=>'Nahrávání se nepodařilo dokončit.','Storage refused the upload (HTTP %d).'=>'Úložisko odmítlo nahrání (HTTP %d).','Style preset'=>'Předvolba stylu','A starting point. Anything below overrides it.'=>'Výchozí bod. Cokoliv níže má před ním přednost.','Use my own colours and sizes'=>'Použít vlastní barvy a velikosti','Leave this off and the preset is used exactly as it is.'=>'Tato možnost musí zůstat vypnutá, aby se přednastavení použilo přesně v takovém stavu, v jakém je.','See the Zinn Digital® release notes.'=>'Prohlédněte si poznámky k vydání Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.']];